-- Check for records that will be excluded from import
PRINT 'Checking records that will be EXCLUDED from import:';
SELECT 
    Warehouse,
    CASE 
        WHEN ItemCode IS NULL THEN 'NULL ItemCode'
        WHEN TreatmentType NOT IN ('FinishedProduct', 'Accessory', 'SubComponent', 'RawMaterial') THEN 'Invalid TreatmentType: ' + ISNULL(TreatmentType, 'NULL')
        ELSE 'Other'
    END AS ExclusionReason,
    COUNT(*) AS ExcludedCount
FROM #StagingImport
WHERE ItemCode IS NULL 
   OR TreatmentType NOT IN ('FinishedProduct', 'Accessory', 'SubComponent', 'RawMaterial')
GROUP BY Warehouse, 
    CASE 
        WHEN ItemCode IS NULL THEN 'NULL ItemCode'
        WHEN TreatmentType NOT IN ('FinishedProduct', 'Accessory', 'SubComponent', 'RawMaterial') THEN 'Invalid TreatmentType: ' + ISNULL(TreatmentType, 'NULL')
        ELSE 'Other'
    END;
