-- Drop unique constraint on SKU if it exists (to allow duplicate SKUs across branches)
IF EXISTS (SELECT * FROM sys.indexes WHERE object_id = OBJECT_ID('Demo_Retail_Product') AND name = 'UQ__Demo_Ret__CA1ECF0D093DC8CA')
