-- Insert missing categories from CSV (don't delete existing due to FK constraints)
PRINT 'Inserting missing categories from CSV...';
SELECT DISTINCT 
    CategoryCode,
    CategoryName,
    1,
    GETDATE(),
    1  -- CreatedBy is INT (UserID), using 1 for System/Admin
FROM (
    SELECT DISTINCT
        LEFT(UPPER(REPLACE(s.Category, ' ', '')), 10) AS CategoryCode,
        s.Category AS CategoryName,
        ROW_NUMBER() OVER (PARTITION BY LEFT(UPPER(REPLACE(s.Category, ' ', '')), 10) ORDER BY s.Category) AS RowNum
    FROM #StagingImport s
    WHERE s.Category IS NOT NULL
        AND s.Category != ''
        AND NOT EXISTS (SELECT 1 FROM ProductCategories WHERE CategoryName = s.Category)
) AS CatData
WHERE RowNum = 1
    AND NOT EXISTS (SELECT 1 FROM ProductCategories WHERE CategoryCode = CatData.CategoryCode);

PRINT CAST(@@ROWCOUNT AS NVARCHAR) + ' new categories created from CSV.';
GO

-- First, let's check for duplicate SKUs that would be generated
PRINT 'Checking for potential SKU duplicates...';
SELECT 
    CASE 
        WHEN s.Barcode IS NOT NULL 
            AND s.Barcode != '0' 
            AND s.Barcode != '' 
            AND s.Barcode NOT LIKE '%[^0-9]%'
            AND LEN(s.Barcode) >= 4 THEN 
            CASE 
                WHEN s.ProductType = 'Internal' THEN '2' + RIGHT('00000000' + s.Barcode, 8)
                ELSE s.Barcode
            END
        ELSE s.ItemCode
    END AS GeneratedSKU,
    COUNT(*) AS DuplicateCount
FROM #StagingImport s
WHERE s.TreatmentType IN ('FinishedProduct', 'Accessory')
    AND s.ItemCode IS NOT NULL
GROUP BY 
    CASE 
        WHEN s.Barcode IS NOT NULL 
            AND s.Barcode != '0' 
            AND s.Barcode != '' 
            AND s.Barcode NOT LIKE '%[^0-9]%'
            AND LEN(s.Barcode) >= 4 THEN 
            CASE 
                WHEN s.ProductType = 'Internal' THEN '2' + RIGHT('00000000' + s.Barcode, 8)
                ELSE s.Barcode
            END
        ELSE s.ItemCode
    END
HAVING COUNT(*) > 1;
GO

-- Now insert with Branch Prefix + ItemCode to ensure uniqueness across branches
-- Include BranchID, CategoryID, and use Barcode field for SKU generation
SELECT 
    PrefixedCode,
    ItemDescription,
    ItemDescription,
    ProductType,
    ExternalBarcode,
    GeneratedSKU,
    BranchID,
    CategoryID,
    Category,
    1,
    GETDATE()
FROM (
    SELECT 
        ISNULL(s.BranchPrefix, '') + s.ItemCode AS PrefixedCode,
        s.ItemDescription,
        s.ProductType,
        s.BranchID,
        s.Category,
        -- CategoryID: Get from ProductCategories table based on category name (NULL if not found)
        (SELECT TOP 1 CategoryID FROM ProductCategories WHERE CategoryName = s.Category) AS CategoryID,
        -- ExternalBarcode: Store original barcode for external products
        CASE WHEN s.ProductType = 'External' AND s.Barcode IS NOT NULL AND s.Barcode != '0' AND s.Barcode != '' THEN s.Barcode ELSE NULL END AS ExternalBarcode,
        -- SKU: Use Barcode field WITHOUT branch prefix (users need to scan actual barcode)
        -- SKU can be duplicate across branches - that's OK!
        CASE 
            WHEN s.Barcode IS NOT NULL 
                AND s.Barcode != '0' 
                AND s.Barcode != '' 
                AND s.Barcode NOT LIKE '%[^0-9]%'
                AND LEN(s.Barcode) >= 4 THEN 
                CASE 
                    WHEN s.ProductType = 'Internal' THEN '2' + RIGHT('00000000' + s.Barcode, 8)
                    ELSE s.Barcode
                END
            ELSE s.ItemCode
        END AS GeneratedSKU,
        ROW_NUMBER() OVER (PARTITION BY ISNULL(s.BranchPrefix, '') + s.ItemCode ORDER BY s.ItemCode) AS RowNum
    FROM #StagingImport s
    WHERE s.TreatmentType IN ('FinishedProduct', 'Accessory', 'SubComponent', 'RawMaterial')
        AND s.ItemCode IS NOT NULL
) AS Deduplicated
WHERE RowNum = 1
    AND NOT EXISTS (SELECT 1 FROM Demo_Retail_Product WHERE Code = Deduplicated.PrefixedCode);
GO

