-- =====================================================
-- STEP 6: Update Master Product Table (WITHOUT branch prefix)
-- =====================================================
PRINT '';
PRINT 'Updating master Products table...';
GO

-- =====================================================
-- Update Master Products Table (WITHOUT branch prefix)
-- Schema: ProductID, ProductCode, ProductName, CategoryID, SubcategoryID, 
--         ItemType, BaseUoM, Dimensions, IsActive, CreatedDate, 
--         ProductImage, SKU, LastPaidPrice, AverageCost, RecommendedSellingPrice
-- =====================================================
IF OBJECT_ID('Products', 'U') IS NOT NULL
BEGIN
    PRINT 'Found master table: Products';
    
    -- Delete existing Demo_Retail products from master Products table (using unprefixed code)
    DELETE FROM Products 
    WHERE ProductCode IN (
        SELECT DISTINCT REPLACE(REPLACE(Code, 'AC', ''), 'UM', '') 
        FROM Demo_Retail_Product
    );
    PRINT CAST(@@ROWCOUNT AS NVARCHAR) + ' existing products removed from master Products table.';
    
    -- Insert Demo_Retail products into master Products table WITHOUT branch prefix
    -- Only insert unique products (not branch-specific duplicates)
    -- Only insert products with valid CategoryID (not NULL)
    SELECT 
        ProductCode,
        ProductName,
        CategoryID,
        ItemType,
        SKU,
        IsActive,
        CreatedDate
    FROM (
        SELECT DISTINCT
            REPLACE(REPLACE(Code, 'AC', ''), 'UM', '') AS ProductCode,
            Name AS ProductName,
            CategoryID,
            ProductType AS ItemType,
            SKU,
            IsActive,
            CreatedAt AS CreatedDate,
            ROW_NUMBER() OVER (PARTITION BY REPLACE(REPLACE(Code, 'AC', ''), 'UM', '') ORDER BY Code) AS RowNum
        FROM Demo_Retail_Product
        WHERE CategoryID IS NOT NULL
    ) AS UniqueProducts
    WHERE RowNum = 1
        AND NOT EXISTS (
            SELECT 1 FROM Products 
            WHERE Products.ProductCode = UniqueProducts.ProductCode
        );
    
    PRINT CAST(@@ROWCOUNT AS NVARCHAR) + ' unique products added to master Products table.';
    PRINT 'Master Products table updated successfully!';
END
ELSE
BEGIN
    PRINT 'WARNING: Master Products table not found. Skipping master table update.';
    PRINT 'Please check table name and update script accordingly.';
END
GO

